<script setup lang="ts">
import type {Field} from '../domain';
import {defineAsyncComponent} from 'vue';
const RegionPicker=defineAsyncComponent(()=>import('./RegionPicker.vue'));
defineProps<{visible:boolean;title:string;fields:Field[];model:Record<string,unknown>;error:string;busy:boolean;submit?:string}>();defineEmits<{close:[];save:[]}>();
</script>
<template><el-dialog :model-value="visible" :title="title" width="760px" :close-on-click-modal="false" @close="$emit('close')"><el-form label-position="top" class="form-grid" @submit.prevent="$emit('save')"><el-form-item v-for="f in fields" :key="f.key" :label="f.label" :required="f.required" :class="{wide:f.type==='region-picker'}"><RegionPicker v-if="f.type==='region-picker'" v-model="model[f.key]"/><el-select v-else-if="f.options" v-model="model[f.key]" :multiple="f.multiple" :aria-label="f.label" :disabled="f.readonly" clearable><el-option v-for="o in f.options" :key="typeof o==='string'?o:o.value" :label="typeof o==='string'?o:o.label" :value="typeof o==='string'?o:o.value"/></el-select><el-input-number v-else-if="f.type==='number'" v-model="model[f.key]" :min="f.min" :max="f.max" :disabled="f.readonly" :aria-label="f.label"/><el-switch v-else-if="f.type==='boolean'" v-model="model[f.key]" :disabled="f.readonly" :aria-label="f.label"/><el-input v-else v-model="model[f.key]" :type="f.type||'text'" :aria-label="f.label" :readonly="f.readonly" :show-password="f.type==='password'"/></el-form-item><slot/><el-alert v-if="error" class="wide" type="error" :title="error" :closable="false"/><div class="dialog-footer wide"><el-button @click="$emit('close')">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">{{submit||'保存'}}</el-button></div></el-form></el-dialog></template>
